import sympy as sp
import scipy.integrate as integrate
import numpy as np

# Define the integral numerically
def integrand(x):
    return x / (np.sin(2*x)**4 + np.cos(2*x)**4)

val, err = integrate.quad(integrand, 0, np.pi/4)

options = {
    1: np.sqrt(2) * np.pi**2 / 8,
    2: np.sqrt(2) * np.pi**2 / 16,
    3: np.sqrt(2) * np.pi**2 / 32,
    4: np.sqrt(2) * np.pi**2 / 64,
}

print(f"Numerical value: {val}")
for k, v in options.items():
    print(f"Option ({k}): {v}")

def f(x):
    import numpy as np
    if x > 0:
        return np.log(x)
    else:
        return np.exp(-x)

def g(x):
    import numpy as np
    if x >= 0:
        return x
    else:
        return np.exp(x)

def gof(x):
    return g(f(x))

import numpy as np
print("gof(0) =", gof(0))
print("gof(np.e) =", gof(np.e))
print("gof(-np.log(2)) =", gof(-np.log(2)))
print("gof(np.exp(2)) =", gof(np.exp(2)))

